  </label>
);

const THEMES = {
  base: { label: "默认主题", page: "bg-surface text-ink-1", card: "border-line-1", line: "bg-press", meta: "text-ink-3" },
  inverse: { label: "反色主题", page: "bg-ink-1 text-ink-inverse", card: "border-ink-2", line: "bg-ink-2", meta: "text-ink-3" },
};
const POSTS = ["View Transition 入门", "伪元素树拆解"];

const STYLE = `
  @scope {
    .cb-range { accent-color: var(--tau-accent); }
  }
`;

const Component = () => {
  const uid = useUid();
  const { rootRef, run, log } = useViewTransition(uid);
  const [theme, setTheme] = useState("base");
  const [wrapped, setWrapped] = useState(true);
  const [duration, setDuration] = useState(800);
  const current = THEMES[theme];
  const next = theme === "base" ? "inverse" : "base";

  const toggle = () => {
    if (wrapped) run(() => setTheme(next), { duration, includeRoot: true });
    else setTheme(next);
  };

  return (
    <div ref={rootRef} className="@container flex flex-col gap-3">
