                aria-label="切换主题"
                onClick={toggle}
                className="ml-auto grid size-7 cursor-pointer place-items-center rounded-full border border-current opacity-80 hover:opacity-100"
              >
                {theme === "base" ? <icons.Moon className="size-3.5" /> : <icons.Sun className="size-3.5" />}
              </button>
            </div>
            {POSTS.map(title => (
              <div key={title} className={`flex flex-col gap-2 rounded-tau-sm border p-3 ${current.card}`}>
                <span className="text-tau-body">{title}</span>
                <span className={`h-2 w-full rounded-full ${current.line}`} />
                <span className={`h-2 w-3/5 rounded-full ${current.line}`} />
              </div>
            ))}
          </div>
        </div>
        <TransitionPanel log={log} hint="切换主题：没有设置任何 name，只会生成 root" />
      </div>
      <div className="flex flex-wrap items-center gap-3">
        <ui.Button variant="primary" size="sm" icon={icons.SunMoon} onClick={toggle}>
          切换主题
        </ui.Button>
        <ui.Switch checked={wrapped} onCheckedChange={setWrapped} label="包进 startViewTransition" />
        <span className="text-tau-meta text-ink-3">当前：{current.label}</span>
        <SlowMotion value={duration} onChange={setDuration} />
      </div>
    </div>
  );
};

