const shuffle = list => {
  const next = [...list];
  do {
    for (let i = next.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [next[i], next[j]] = [next[j], next[i]];
    }
  } while (next.every((item, index) => item === list[index]));
  return next;
};

const Component = () => {
  const uid = useUid();
  const { rootRef, run, log } = useViewTransition(uid);
  const [items, setItems] = useState(ITEMS);
  const [withName, setWithName] = useState(true);
  const [duration, setDuration] = useState(800);

  const apply = transform => run(() => setItems(transform), { duration });

  return (
    <div ref={rootRef} data-named={withName ? "" : undefined} className="@container flex flex-col gap-3">
