                {item.id}
              </span>
              <span className="min-w-0 truncate text-tau-body text-ink-1">{item.label}</span>
              <span className="ml-auto shrink-0 font-tau-mono text-tau-tiny text-ink-3">第 {index + 1} 位</span>
            </div>
          ))}
        </div>
        <TransitionPanel log={log} />
      </div>
      <div className="flex flex-wrap items-center gap-3">
        <ui.Button variant="primary" size="sm" icon={icons.Shuffle} onClick={() => apply(shuffle)}>
          打乱顺序
        </ui.Button>
        <ui.Button variant="secondary" size="sm" icon={icons.ArrowDownUp} onClick={() => apply(list => [...list].reverse())}>
          反转
        </ui.Button>
        <ui.Switch checked={withName} onCheckedChange={setWithName} label="设置 view-transition-name" />
        <Chip>{withName ? "item-1 … item-6" : "none"}</Chip>
        <SlowMotion value={duration} onChange={setDuration} />
      </div>
    </div>
  );
};

