const named = (uid, name, style) => ({ ...style, "--cb-vt-name": `${uid}-${name}` });

const TIMEOUT_MS = 4000;
const ARTICLE = { title: "跨文档视图过渡", meta: "@view-transition · 同源导航", icon: icons.Globe };

const STYLE = `
  @scope {
    :scope[data-vt-live] .cb-vt { view-transition-name: var(--cb-vt-name); }
    .cb-range { accent-color: var(--tau-accent); }
    .cb-loading { animation: cb-mpa-load var(--cb-load) linear forwards; }
  }
  @keyframes cb-mpa-load {
    from { width: 0%; }
    to { width: 100%; }
