    height: 100%;
    object-fit: cover;
  }
`;

const Component = () => {
  const uid = useUid();
  const { rootRef, run, log } = useViewTransition(uid);
  const timerRef = useRef(0);
  const [page, setPage] = useState("list");
  const [delay, setDelay] = useState(500);
  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState("");

  useEffect(() => () => clearTimeout(timerRef.current), []);

  const navigate = () => {
    if (loading) return;
    setLoading(true);
    setStatus("");
    timerRef.current = setTimeout(() => {
      setLoading(false);
      const transition = run(() => setPage("detail"));
      // 新页面超过 4s 才就绪：浏览器放弃过渡，直接显示新页面
      if (delay > TIMEOUT_MS) {
        transition?.skipTransition();
        setStatus(`就绪耗时 ${delay / 1000}s，超过 4s，跳过过渡`);
      } else {
        setStatus(`就绪耗时 ${delay / 1000}s，执行过渡`);
      }
    }, delay);
  };
  const back = () => {
    clearTimeout(timerRef.current);
    setLoading(false);
    setStatus("");
    run(() => setPage("list"));
  };

  const hero = (className, iconClass) => (
    <div
      className={`cb-vt grid shrink-0 place-items-center rounded-tau-sm bg-tag-2-soft text-tag-2 ${className}`}
