                    <span className="text-tau-body text-ink-1">{ARTICLE.title}</span>
                    <span className="truncate text-tau-meta text-ink-3">{ARTICLE.meta}</span>
                  </span>
                </button>
                <div className="flex items-center gap-3 rounded-tau-sm border border-line-2 p-2 opacity-60">
                  <span className="size-16 shrink-0 rounded-tau-sm bg-hover" />
                  <span className="flex flex-1 flex-col gap-2">
                    <span className="h-2 w-2/5 rounded-full bg-press" />
                    <span className="h-2 w-3/5 rounded-full bg-press" />
                  </span>
                </div>
                {loading && <span className="text-tau-meta text-ink-3">加载中，旧页面保持可见</span>}
              </>
            ) : (
              <>
                {hero("aspect-[21/9] w-full", "size-12")}
                <h4 className="cb-vt m-0 w-fit text-tau-title text-ink-1" style={named(uid, "page-title")}>
                  {ARTICLE.title}
                </h4>
                <span className="h-2 w-full rounded-full bg-press" />
                <span className="h-2 w-4/5 rounded-full bg-press" />
              </>
            )}
