const { useEffect, useLayoutEffect, useMemo, useRef, useState } = React;

// ---- View Transition 实验台（本文各块共用）----

const PHASES = [
  { key: "start", label: "startViewTransition()" },
  { key: "updateCallbackDone", label: "updateCallbackDone" },
  { key: "ready", label: "ready" },
  { key: "finished", label: "finished" },
];
const PSEUDO = /^::view-transition-(group|old|new)\((.+)\)$/;

// 每个块实例一个前缀，同一篇文章多处挂载时 view-transition-name 也不会重复
const useUid = () => useMemo(() => `cb${Math.random().toString(36).slice(2, 8)}`, []);

const ownAnimations = (uid, includeRoot) =>
  document.getAnimations().filter(animation => {
    const name = animation.effect?.pseudoElement?.match(PSEUDO)?.[2];
    return name && (name.startsWith(`${uid}-`) || (includeRoot && name === "root"));
  });

// 从浏览器真实生成的伪元素动画里还原本次过渡的 group 列表
const collectGroups = uid => {
  const groups = new Map();
  for (const animation of document.getAnimations()) {
    const match = animation.effect?.pseudoElement?.match(PSEUDO);
    if (!match) continue;
    const [, part, name] = match;
    if (name !== "root" && !name.startsWith(`${uid}-`)) continue;
    const label = name === "root" ? "root" : name.slice(uid.length + 1);
    const entry = groups.get(label) ?? { name: label, old: false, new: false, duration: 0 };
    if (part !== "group") entry[part] = true;
    const duration = Number(animation.effect.getTiming().duration) || 0;
    if (part === "group" || !entry.duration) entry.duration = Math.round(duration);
    groups.set(label, entry);
  }
  return [...groups.values()].sort((a, b) => (a.name === "root" ? -1 : b.name === "root" ? 1 : 0));
};

const useViewTransition = uid => {
  const rootRef = useRef(null);
  const commitRef = useRef(null);
  const activeRef = useRef(null);
  const [log, setLog] = useState(null);

  // React 提交 DOM 后放行 update 回调返回的 Promise，浏览器随后截取新视图
  useLayoutEffect(() => {
    commitRef.current?.();
    commitRef.current = null;
  });
  useEffect(
    () => () => {
      commitRef.current?.();
      activeRef.current?.skipTransition();
    },
    []
  );

  const run = (update, { types, duration, includeRoot = false, onReady } = {}) => {
    const root = rootRef.current;
    if (!document.startViewTransition || !root) {
      update();
      setLog({ unsupported: true, times: {}, groups: [] });
      return null;
    }
    activeRef.current?.skipTransition();
    const begin = performance.now();
    const mark = (key, extra) =>
      setLog(current =>
        current?.id === begin ? { ...current, ...extra, times: { ...current.times, [key]: Math.round(performance.now() - begin) } } : current
      );
    setLog({ id: begin, times: { start: 0 }, groups: [], types: types ?? [] });
    // 过渡期间才让元素带上 view-transition-name，结束后撤掉，不影响应用自身的过渡
    root.setAttribute("data-vt-live", "");
    const transition = document.startViewTransition({
      update: () =>
        new Promise(resolve => {
          commitRef.current = resolve;
          update();
          setTimeout(resolve, 600);
        }),
      types,
    });
    activeRef.current = transition;
    transition.updateCallbackDone.then(() => mark("updateCallbackDone"), () => {});
    transition.ready.then(
      () => {
        if (duration) ownAnimations(uid, includeRoot).forEach(animation => animation.effect.updateTiming({ duration }));
        onReady?.(transition);
        mark("ready", { groups: collectGroups(uid), types: [...(transition.types ?? types ?? [])] });
      },
      error => mark("ready", { error: `${error.name}: ${error.message}` })
    );
    transition.finished
      .catch(() => {})
      .finally(() => {
        mark("finished");
        if (activeRef.current !== transition) return;
        activeRef.current = null;
        root.removeAttribute("data-vt-live");
      });
    return transition;
  };

  return { rootRef, run, log };
};

const TransitionPanel = ({ log, hint = "触发一次过渡后，这里列出浏览器生成的 group" }) => (
  <div className="flex min-w-0 flex-col gap-2">
    <span className="text-tau-sm text-ink-3">过渡记录</span>
    <ol className="m-0 flex list-none flex-col gap-1 rounded-tau-md bg-hover px-3 py-2.5">
      {PHASES.map(phase => {
        const time = log?.times?.[phase.key];
        const done = time !== undefined;
        return (
          <li key={phase.key} className="flex min-w-0 items-center gap-2 font-tau-mono text-tau-sm">
            <span className={`size-1.5 shrink-0 rounded-full ${done ? "bg-ok" : "bg-line-1"}`} />
            <span className={`min-w-0 truncate ${done ? "text-ink-1" : "text-ink-3"}`}>{phase.label}</span>
            <span className="ml-auto shrink-0 text-ink-3">{done ? `${time}ms` : "—"}</span>
          </li>
        );
      })}
    </ol>
    <div className="flex min-h-[96px] flex-col gap-1 rounded-tau-md border border-line-1 bg-surface p-3 font-tau-mono text-tau-sm text-ink-2">
      <span className="text-ink-3">::view-transition</span>
      {log?.groups?.map((group, index) => (
        <div key={group.name} className="flex min-w-0 items-center gap-1.5">
          <span className="shrink-0 text-ink-3">{index === log.groups.length - 1 ? "└─" : "├─"}</span>
          <span className="min-w-0 break-all text-ink-1">group({group.name})</span>
          <span className="ml-auto flex shrink-0 items-center gap-1">
            <span className={`rounded-tau-sm px-1 text-tau-tiny ${group.old ? "bg-tag-1-soft text-tag-1" : "text-ink-3 line-through"}`}>old</span>
            <span className={`rounded-tau-sm px-1 text-tau-tiny ${group.new ? "bg-tag-3-soft text-tag-3" : "text-ink-3 line-through"}`}>new</span>
            <span className="w-12 text-right text-tau-tiny text-ink-3">{group.duration}ms</span>
          </span>
        </div>
      ))}
      {log?.error && <span className="m-0 break-all rounded-tau-sm bg-danger-soft px-1.5 py-1 text-tau-tiny text-danger">{log.error}</span>}
      {log?.unsupported && <span className="text-tau-meta text-ink-3">当前环境不支持 View Transition，DOM 直接更新</span>}
      {!log && <span className="font-tau text-tau-meta text-ink-3">{hint}</span>}
    </div>
  </div>
);


const Chip = ({ children }) => (
  <code className="rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-sm text-ink-2">{children}</code>
);

// 过渡期间带上 view-transition-name 的元素：名字经 --cb-vt-name 传给样式
const named = (uid, name, style) => ({ ...style, "--cb-vt-name": `${uid}-${name}` });

const LANGS = [
  { id: "ts", label: "TypeScript" },
  { id: "rust", label: "Rust" },
  { id: "go", label: "Go" },
  { id: "python", label: "Python" },
  { id: "swift", label: "Swift" },
  { id: "kotlin", label: "Kotlin" },
  { id: "zig", label: "Zig" },
  { id: "elixir", label: "Elixir" },
];
const INITIAL = LANGS.map((lang, index) => ({ ...lang, score: 96 - index * 9 }));

const STYLE = `
  @scope {
    :scope[data-vt-live] .cb-vt { view-transition-name: var(--cb-vt-name); }
    :scope[data-classed] .cb-vt { view-transition-class: cb-rank-item; }
  }
  html::view-transition-group(*.cb-rank-item) {
    animation-duration: 0.9s;
    animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1);
  }
`;

const reshuffle = list =>
  list
    .map(item => ({ ...item, score: Math.max(8, Math.min(99, item.score + Math.round((Math.random() - 0.5) * 70))) }))
    .sort((a, b) => b.score - a.score);

const Component = () => {
  const uid = useUid();
  const { rootRef, run, log } = useViewTransition(uid);
  const [rows, setRows] = useState(INITIAL);
  const [classed, setClassed] = useState(true);

  return (
    <div ref={rootRef} data-classed={classed ? "" : undefined} className="@container flex flex-col gap-3">
      <style>{STYLE}</style>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
        <ol className="m-0 flex min-w-0 list-none flex-col gap-1.5 rounded-tau-md border border-line-1 p-4">
          {rows.map((row, index) => (
            <li
              key={row.id}
              className="cb-vt flex min-w-0 items-center gap-3 rounded-tau-sm bg-surface px-2 py-1.5"
              style={named(uid, `item-${row.id}`)}
            >
              <span className="w-5 shrink-0 text-right font-tau-mono text-tau-sm text-ink-3">{index + 1}</span>
              <span className="w-20 shrink-0 truncate text-tau-body text-ink-1">{row.label}</span>
              <span className="h-1.5 min-w-0 flex-1 overflow-hidden rounded-full bg-track">
                <span className="block h-full rounded-full bg-accent" style={{ width: `${row.score}%` }} />
              </span>
              <span className="w-7 shrink-0 text-right font-tau-mono text-tau-sm text-ink-2">{row.score}</span>
            </li>
          ))}
        </ol>
        <TransitionPanel log={log} hint="刷新排名后，对比每个 group 的动画时长" />
      </div>
      <div className="flex flex-wrap items-center gap-3">
        <ui.Button variant="primary" size="sm" icon={icons.ListOrdered} onClick={() => run(() => setRows(reshuffle))}>
          刷新排名
        </ui.Button>
        <ui.Switch checked={classed} onCheckedChange={setClassed} label="view-transition-class: rank-item" />
        <Chip>{classed ? "::view-transition-group(*.rank-item) → 0.9s" : "未命中通配规则 → 默认 0.25s"}</Chip>
      </div>
    </div>
  );
};

