.slide-container {
  view-transition-name: slide;
}

/* group 层做裁剪，保持圆角 */
::view-transition-group(slide) {
  overflow: hidden;
  border-radius: 12px;
}

/* 解除 image-pair 的默认隔离，让 old 和 new 各自独立定位 */
::view-transition-image-pair(slide) {
  isolation: auto;
  overflow: visible;
}

/* 下一张：old 向左推出，new 从右侧紧贴推入 */
html:active-view-transition-type(slide-forward) {
  &::view-transition-old(slide) {
    animation: 0.4s ease both push-out-left;
  }
  &::view-transition-new(slide) {
    animation: 0.4s ease both push-in-from-right;
  }
}

/* 上一张：old 向右推出，new 从左侧紧贴推入 */
html:active-view-transition-type(slide-back) {
  &::view-transition-old(slide) {
    animation: 0.4s ease both push-out-right;
  }
  &::view-transition-new(slide) {
    animation: 0.4s ease both push-in-from-left;
  }
}

@keyframes push-out-left {
  from { transform: translateX(0); }
  to { transform: translateX(-100%); }
}
@keyframes push-in-from-right {
  from { transform: translateX(100%); }
  to { transform: translateX(0); }
}
@keyframes push-out-right {
  from { transform: translateX(0); }
  to { transform: translateX(100%); }
}
@keyframes push-in-from-left {
  from { transform: translateX(-100%); }
  to { transform: translateX(0); }
}

document.getElementById('next').addEventListener('click', () => {
  current = (current + 1) % slides.length;
  document.startViewTransition({
    update: () => render(),
    types: ['slide-forward'],
  });
});

document.getElementById('prev').addEventListener('click', () => {
  current = (current - 1 + slides.length) % slides.length;
  document.startViewTransition({
    update: () => render(),
    types: ['slide-back'],
  });
});

