            <span className="flex flex-col gap-0.5">
              <span className="text-tau-title text-ink-1">{slide.title}</span>
              <span className="text-tau-meta text-ink-2">{slide.note}</span>
            </span>
          </div>
          <div className="flex items-center gap-2">
            <ui.IconButton aria-label="上一张" onClick={() => go(-1)}>
              <icons.ChevronLeft className="size-4" />
            </ui.IconButton>
            <div className="flex flex-1 justify-center gap-1.5">
              {SLIDES.map((item, index) => (
                <span key={item.title} className={`h-1.5 rounded-full transition-all ${index === current ? "w-5 bg-accent" : "w-1.5 bg-line-1"}`} />
              ))}
            </div>
            <ui.IconButton aria-label="下一张" onClick={() => go(1)}>
              <icons.ChevronRight className="size-4" />
            </ui.IconButton>
          </div>
        </div>
        <TransitionPanel log={log} hint="翻页时根据方向传入不同的 types" />
      </div>
      <div className="flex flex-wrap items-center gap-3">
        <ui.Switch checked={typed} onCheckedChange={setTyped} label="传入 types" />
        <Chip>types: [{types}]</Chip>
        <span className="text-tau-meta text-ink-3">{typed ? "按方向推挤" : "未匹配类型，默认淡入淡出"}</span>
        <SlowMotion value={duration} onChange={setDuration} />
      </div>
    </div>
  );
};

