        return (
          <li key={phase.key} className="flex min-w-0 items-center gap-2 font-tau-mono text-tau-sm">
            <span className={`size-1.5 shrink-0 rounded-full ${done ? "bg-ok" : "bg-line-1"}`} />
            <span className={`min-w-0 truncate ${done ? "text-ink-1" : "text-ink-3"}`}>{phase.label}</span>
            <span className="ml-auto shrink-0 text-ink-3">{done ? `${time}ms` : "—"}</span>
          </li>
        );
      })}
    </ol>
    <div className="flex min-h-[96px] flex-col gap-1 rounded-tau-md border border-line-1 bg-surface p-3 font-tau-mono text-tau-sm text-ink-2">
      <span className="text-ink-3">::view-transition</span>
      {log?.groups?.map((group, index) => (
        <div key={group.name} className="flex min-w-0 items-center gap-1.5">
          <span className="shrink-0 text-ink-3">{index === log.groups.length - 1 ? "└─" : "├─"}</span>
          <span className="min-w-0 break-all text-ink-1">group({group.name})</span>
          <span className="ml-auto flex shrink-0 items-center gap-1">
            <span className={`rounded-tau-sm px-1 text-tau-tiny ${group.old ? "bg-tag-1-soft text-tag-1" : "text-ink-3 line-through"}`}>old</span>
            <span className={`rounded-tau-sm px-1 text-tau-tiny ${group.new ? "bg-tag-3-soft text-tag-3" : "text-ink-3 line-through"}`}>new</span>
            <span className="w-12 text-right text-tau-tiny text-ink-3">{group.duration}ms</span>
          </span>
        </div>
      ))}
      {log?.error && <span className="m-0 break-all rounded-tau-sm bg-danger-soft px-1.5 py-1 text-tau-tiny text-danger">{log.error}</span>}
      {log?.unsupported && <span className="text-tau-meta text-ink-3">当前环境不支持 View Transition，DOM 直接更新</span>}
      {!log && <span className="font-tau text-tau-meta text-ink-3">{hint}</span>}
    </div>
  </div>
);

const SlowMotion = ({ value, onChange }) => (
  <label className="flex min-w-[200px] flex-1 items-center gap-3">
    <span className="shrink-0 text-tau-sm text-ink-2">动画时长</span>
    <input type="range" min={250} max={2000} step={50} value={value} onChange={event => onChange(Number(event.target.value))} className="cb-range min-w-0 flex-1" />
    <span className="w-14 shrink-0 text-right font-tau-mono text-tau-sm text-ink-2">{value}ms</span>
  </label>
);

const Chip = ({ children }) => (
  <code className="rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-sm text-ink-2">{children}</code>
);

const PHOTOS = [
  { title: "雪山", icon: icons.Mountain, tone: "bg-tag-1-soft text-tag-1" },
  { title: "海浪", icon: icons.Waves, tone: "bg-tag-2-soft text-tag-2" },
  { title: "森林", icon: icons.Trees, tone: "bg-tag-3-soft text-tag-3" },
  { title: "日落", icon: icons.Sun, tone: "bg-tag-4-soft text-tag-4" },
  { title: "云层", icon: icons.Cloud, tone: "bg-tag-5-soft text-tag-5" },
  { title: "落雪", icon: icons.Snowflake, tone: "bg-accent-soft text-accent-text" },
];

const STYLE = `
  @scope {
    .cb-range { accent-color: var(--tau-accent); }
  }
  html::view-transition-old(*.cb-vt-cover),
  html::view-transition-new(*.cb-vt-cover) {
    height: 100%;
    object-fit: cover;
  }
`;

const Component = () => {
  const uid = useUid();
  const { rootRef, run, log } = useViewTransition(uid);
  const thumbRefs = useRef([]);
  const [openIndex, setOpenIndex] = useState(null);
  const [holder, setHolder] = useState("无");
  const [keepOld, setKeepOld] = useState(false);
  const [duration, setDuration] = useState(700);
  const activeName = `${uid}-active-image`;
  const photo = PHOTOS[openIndex];

  const open = index => {
    const thumb = thumbRefs.current[index];
    // 只给被点击的缩略图设置 name
    thumb.style.viewTransitionName = activeName;
    setHolder(`缩略图「${PHOTOS[index].title}」`);
    const transition = run(
      () => {
        // 交给大图之前先从缩略图上撤掉，同一时刻只能有一个元素持有这个 name
        if (!keepOld) thumb.style.viewTransitionName = "";
        setOpenIndex(index);
        setHolder(keepOld ? "缩略图 + 大图（重复）" : "大图");
      },
      { duration }
    );
    const settle = () => {
      thumb.style.viewTransitionName = "";
      setHolder(current => (current.includes("重复") ? "大图" : current));
    };
    if (transition) transition.finished.finally(settle);
    else settle();
  };

  const close = () => {
    const thumb = thumbRefs.current[openIndex];
    const transition = run(
      () => {
        // 大图卸载后 name 随之消失，再交还给缩略图，浏览器生成收回动画
        thumb.style.viewTransitionName = activeName;
        setOpenIndex(null);
        setHolder(`缩略图「${PHOTOS[openIndex].title}」`);
      },
      { duration }
    );
    const clear = () => {
      thumb.style.viewTransitionName = "";
      setHolder("无");
    };
    if (transition) transition.finished.finally(clear);
    else clear();
  };

  useEffect(() => () => thumbRefs.current.forEach(thumb => thumb && (thumb.style.viewTransitionName = "")), []);

  return (
    <div ref={rootRef} className="@container flex flex-col gap-3">
      <style>{STYLE}</style>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
        <div className="relative min-w-0 rounded-tau-md border border-line-1 p-4">
          <div className="grid grid-cols-3 gap-2">
            {PHOTOS.map((item, index) => (
              <button
                key={item.title}
                ref={element => (thumbRefs.current[index] = element)}
                type="button"
                onClick={() => open(index)}
                className={`flex aspect-square cursor-pointer flex-col items-center justify-center gap-1 rounded-tau-sm transition-opacity hover:opacity-80 ${item.tone}`}
                style={{ viewTransitionClass: "cb-vt-cover" }}
              >
                <item.icon className="size-6" strokeWidth={1.5} />
                <span className="text-tau-tiny">{item.title}</span>
              </button>
            ))}
          </div>
          {photo && (
            <div className="absolute inset-0 flex flex-col gap-3 rounded-tau-md bg-surface p-4">
              <div className="flex items-center gap-2">
                <span className="text-tau-body text-ink-1">{photo.title}</span>
                <span className="font-tau-mono text-tau-tiny text-ink-3">{openIndex + 1} / {PHOTOS.length}</span>
                <ui.Button variant="ghost" size="sm" icon={icons.X} className="ml-auto" onClick={close}>
                  关闭
                </ui.Button>
              </div>
              <div
                className={`grid min-h-0 flex-1 place-items-center rounded-tau-sm ${photo.tone}`}
                style={{ viewTransitionName: activeName, viewTransitionClass: "cb-vt-cover" }}
              >
                <photo.icon className="size-14" strokeWidth={1.5} />
              </div>
            </div>
          )}
        </div>
        <TransitionPanel log={log} hint="点击任一缩略图打开大图" />
      </div>
      <div className="flex flex-wrap items-center gap-3">
        <ui.Switch checked={keepOld} onCheckedChange={setKeepOld} label="不撤掉缩略图的 name" />
        <Chip>active-image：{holder}</Chip>
        <SlowMotion value={duration} onChange={setDuration} />
      </div>
    </div>
  );
};

